      INTEGER FUNCTION NIV(TYPE)CC     RETURNS NUMBER OF POSSIBLY INDICATED VARIED PARAMETERSCC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA0A.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'ELM17A.CIN'CC     LOCAL VARIABLESC      INTEGER  NV1(NELMCT), TYPEC      DATA NV1 /6, 1, 1, 3, 2, 0, 6, 6, 0, 0,     1          0,15, 0, 6, 0, 2, 0, 0, 2, 1,     2          0, 0, 0, 0, 0, 0, 6, 2, 2, 1,     3          0, 0, 0, 2, 2, 2, 0, 0, 0, 0,     4          0, 3, 6, 0, 0, 1, 1, 1/CC-----------------------------------------------------------------      NIV = NV1(TYPE)      IF (TYPE .EQ. 1 .AND. NORD3 .GT. 1) NIV = 0      IF (TYPE .EQ. 8 .AND. NORD3 .GT. 1) NIV = 0      IF (TYPE .EQ. 12 .AND. NORD3 .GT. 1) NIV = 0      IF (TYPE .EQ. 16) THEN        IDP = INT(DATA(I+1))        IF (IDP .GE. 16 .AND. IDP .LE. 20) NIV = 2        IF (IDP .GE. 22 .AND. IDP .LE. 25) NIV = 2      ENDIF      IF (TYPE .EQ. 18 .AND. NORD1 .GE. 2) NIV = 2      IF (TYPE .EQ. 25 .AND. NORD1 .GE. 3) NIV = 2      RETURN      END